def norm(cells):
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    mr,mc=min(rs),min(cs)
    s=tuple(sorted((r-mr,c-mc) for r,c in cells))
    # canonical under dihedral group
    def t(shapes):
        best=min(shapes,key=len)
        pts=list(best)
        for flip in (lambda a,b:(a,-b),lambda a,b:(-a,b)):
